#!/bin/bash
set -uo pipefail
WT=/home/nolan/fyd-preview-wt
PD=/home/nolan/fyd-preview-patches
mkdir -p "$PD"
base64 -d > "$PD/o-capability-safe-link.patch" <<'PATCHEOF64'

PATCHEOF64
base64 -d > "$PD/o-contact-block-safe-link.patch" <<'PATCHEOF64'

PATCHEOF64
base64 -d > "$PD/display-media-src-allowlist.patch" <<'PATCHEOF64'

PATCHEOF64
base64 -d > "$PD/export-customer-data-script-escape.patch" <<'PATCHEOF64'

PATCHEOF64
base64 -d > "$PD/safe-link-email-shape-tighten.patch" <<'PATCHEOF64'

PATCHEOF64
cd "$WT"
for f in "$PD"/*.patch; do
  p=$(basename "$f")
  echo "=== CHECK $p ==="
  if git apply --check --verbose "$f" 2>&1; then echo "CHECK_OK: $p"; else echo "CHECK_FAIL: $p"; fi
done
echo "PATCH_FILES_SHA:"
sha256sum "$PD"/*.patch
